// cast series to int
to_int(val) =>
    k = 0
    p = 0 // 0.0
    d = 0.0 // can't be 0 int => can't assign series to int error
    pow = 1
    // for i = floor(val) to round(val)
    // for i = 1 to round(val)
    s = val
    for i = 0 to 9
        // get last digit
        d := s % 10 // s - floor(s/10)*10
        // k := k + 1 can't be inside if => series
        // if s > 0
        k := -1
        for j = 0 to 9
            k := k + 1
            if j == d
                break

        pow := 1
        if i > 0
            for m = 0 to i-1
                pow := 10 * pow
        
        p := p + k * pow // can't use pow(10, i) => series
        
        s := floor(s/10)        
        if s == 0
            break
    p

